//
// Minimal Verilator testbench for the LiteX VexRiscv netlists (Wishbone instruction and data
// buses, as generated by pythondata-cpu-vexriscv's GenCoreDefault). It models what a LiteX SoC
// gives the core: RAM, a console, an exit register, a CLINT-style timer and software interrupt
// and the 32-bit external interrupt array.
//
// Memory map:
//   0x4000_0000 - 0x4FFF_FFFF  RAM (256 MiB; LiteX main_ram base)
//   0xF000_0000                console: a byte written here goes to stdout
//   0xF000_0004                exit: the word written here is the simulator's exit status
//   0xF000_0008                externalInterruptArray (read/write)
//   0xF001_0000                msip (bit 0 drives softwareInterrupt)
//   0xF001_4000 / 0xF001_4004  mtimecmp low / high
//   0xF001_BFF8 / 0xF001_BFFC  mtime low / high (+1 every MTIME_DIV = 10 cycles)
//   anything else              acknowledged with ERR set and read data 0
//
// The netlist's Wishbone bridges ignore ERR (rsp.error := False in VexRiscv's
// InstructionCache.toWishbone and DataCache.toWishbone) and wait for ACK, so an access that got
// only ERR would hang the core. A LiteX SoC ends such an access with ACK and ERR from its bus
// timeout; the testbench does the same at once. The core never takes an access fault.
//
// Each Wishbone beat is acknowledged one cycle after the request (registered ack), and ack
// drops for a cycle between beats, as in LiteX's wishbone.SRAM.
//
// Usage: vexriscv-tb <elf> [+max-cycles=N] [+trace-fetch]
// +trace-fetch prints the address of every instruction-bus beat to stderr.
// Exit status: the value written to the exit register, 3 at the cycle limit, 2 on usage error.

#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>

#include "VVexRiscv.h"
#include "verilated.h"

static const uint32_t RAM_BASE = 0x40000000u;
static const uint32_t RAM_SIZE = 0x10000000u;
static const uint32_t IO_CONSOLE = 0xF0000000u;
static const uint32_t IO_EXIT = 0xF0000004u;
static const uint32_t IO_EXTINT = 0xF0000008u;
static const uint32_t CLINT_MSIP = 0xF0010000u;
static const uint32_t CLINT_MTIMECMP = 0xF0014000u;
static const uint32_t CLINT_MTIME = 0xF001BFF8u;
static const uint64_t MTIME_DIV = 10;

static uint8_t *ram;

static bool load_elf(const char *path) {
  FILE *f = fopen(path, "rb");
  if (!f) return false;
  std::vector<uint8_t> buf;
  uint8_t tmp[65536];
  size_t n;
  while ((n = fread(tmp, 1, sizeof tmp, f)) > 0) buf.insert(buf.end(), tmp, tmp + n);
  fclose(f);
  if (buf.size() < 52 || memcmp(buf.data(), "\x7f" "ELF", 4) != 0 || buf[4] != 1) {
    fprintf(stderr, "vexriscv-tb: %s is not a 32-bit ELF\n", path);
    return false;
  }
  auto rd32 = [&](size_t o) { uint32_t v; memcpy(&v, &buf[o], 4); return v; };
  auto rd16 = [&](size_t o) { uint16_t v; memcpy(&v, &buf[o], 2); return v; };
  uint32_t phoff = rd32(28);
  uint16_t phentsize = rd16(42), phnum = rd16(44);
  for (unsigned i = 0; i < phnum; i++) {
    size_t ph = phoff + (size_t)i * phentsize;
    if (rd32(ph) != 1) continue;  // PT_LOAD
    uint32_t offset = rd32(ph + 4), paddr = rd32(ph + 12), filesz = rd32(ph + 16), memsz = rd32(ph + 20);
    if (memsz == 0) continue;
    if (paddr < RAM_BASE || (uint64_t)paddr + memsz > (uint64_t)RAM_BASE + RAM_SIZE) {
      fprintf(stderr, "vexriscv-tb: segment at 0x%08x (+0x%x) is outside RAM\n", paddr, memsz);
      return false;
    }
    memcpy(ram + (paddr - RAM_BASE), &buf[offset], filesz);
  }
  return true;
}

int main(int argc, char **argv) {
  const char *elf = nullptr;
  uint64_t max_cycles = 50000000;
  bool trace_fetch = false;
  for (int i = 1; i < argc; i++) {
    if (!strncmp(argv[i], "+max-cycles=", 12)) max_cycles = strtoull(argv[i] + 12, nullptr, 0);
    else if (!strcmp(argv[i], "+trace-fetch")) trace_fetch = true;
    else if (argv[i][0] != '+') elf = argv[i];
  }
  if (!elf) {
    fprintf(stderr, "Usage: vexriscv-tb <elf> [+max-cycles=N] [+trace-fetch]\n");
    return 2;
  }
  ram = (uint8_t *)calloc(RAM_SIZE, 1);
  if (!ram || !load_elf(elf)) return 2;

  VerilatedContext *ctx = new VerilatedContext;
  ctx->commandArgs(argc, argv);
  VVexRiscv *top = new VVexRiscv(ctx);

  uint64_t mtime = 0, mtimecmp = ~0ull;
  uint32_t ext_irq = 0;
  bool msip = false;
  bool iack = false, dack = false;

  top->externalResetVector = RAM_BASE;
  top->timerInterrupt = 0;
  top->softwareInterrupt = 0;
  top->externalInterruptArray = 0;
  top->iBusWishbone_ACK = 0;
  top->iBusWishbone_ERR = 0;
  top->dBusWishbone_ACK = 0;
  top->dBusWishbone_ERR = 0;
  top->reset = 1;
  top->clk = 0;
  top->eval();

  for (uint64_t cycle = 0;; cycle++) {
    if (cycle == 16) top->reset = 0;
    if (cycle >= max_cycles) {
      fflush(stdout);
      fprintf(stderr, "vexriscv-tb: cycle limit (%llu) reached\n", (unsigned long long)max_cycles);
      return 3;
    }
    // Outputs now reflect the state after the previous rising edge; compute the inputs that the
    // next rising edge samples.
    // Instruction bus: read-only, RAM only.
    top->iBusWishbone_ACK = 0;
    top->iBusWishbone_ERR = 0;
    if (iack) {
      iack = false;
    } else if (top->iBusWishbone_CYC && top->iBusWishbone_STB) {
      uint32_t a = (uint32_t)top->iBusWishbone_ADR << 2;
      top->iBusWishbone_ACK = 1;
      if (a >= RAM_BASE && a - RAM_BASE < RAM_SIZE) {
        uint32_t v;
        memcpy(&v, ram + (a - RAM_BASE), 4);
        top->iBusWishbone_DAT_MISO = v;
      } else {
        top->iBusWishbone_DAT_MISO = 0;
        top->iBusWishbone_ERR = 1;
      }
      iack = true;
      if (trace_fetch) fprintf(stderr, "I %08x\n", a);
    }
    // Data bus
    top->dBusWishbone_ACK = 0;
    top->dBusWishbone_ERR = 0;
    if (dack) {
      dack = false;
    } else if (top->dBusWishbone_CYC && top->dBusWishbone_STB) {
      uint32_t a = (uint32_t)top->dBusWishbone_ADR << 2;
      uint32_t sel = top->dBusWishbone_SEL;
      bool we = top->dBusWishbone_WE;
      uint32_t wdata = top->dBusWishbone_DAT_MOSI;
      uint32_t rdata = 0;
      bool err = false;
      if (a >= RAM_BASE && a - RAM_BASE < RAM_SIZE) {
        uint8_t *p = ram + (a - RAM_BASE);
        if (we) {
          for (int b = 0; b < 4; b++)
            if (sel & (1u << b)) p[b] = (uint8_t)(wdata >> (8 * b));
        } else {
          memcpy(&rdata, p, 4);
        }
      } else if (a == IO_CONSOLE) {
        if (we) {
          for (int b = 0; b < 4; b++)
            if (sel & (1u << b)) {
              putchar((int)(uint8_t)(wdata >> (8 * b)));
              break;
            }
        }
      } else if (a == IO_EXIT) {
        if (we) {
          fflush(stdout);
          int code = (int)wdata;
          top->final();
          delete top;
          return code;
        }
      } else if (a == IO_EXTINT) {
        if (we) ext_irq = wdata;
        rdata = ext_irq;
      } else if (a == CLINT_MSIP) {
        if (we) msip = wdata & 1;
        rdata = msip;
      } else if (a == CLINT_MTIMECMP || a == CLINT_MTIMECMP + 4) {
        int sh = (a == CLINT_MTIMECMP) ? 0 : 32;
        uint64_t mask = 0xFFFFFFFFull << sh;
        uint64_t cur = (mtimecmp & mask) >> sh;
        uint32_t nv = (uint32_t)cur;
        for (int b = 0; b < 4; b++)
          if (we && (sel & (1u << b))) nv = (nv & ~(0xFFu << (8 * b))) | (wdata & (0xFFu << (8 * b)));
        if (we) mtimecmp = (mtimecmp & ~mask) | ((uint64_t)nv << sh);
        rdata = (uint32_t)(mtimecmp >> sh);
      } else if (a == CLINT_MTIME || a == CLINT_MTIME + 4) {
        int sh = (a == CLINT_MTIME) ? 0 : 32;
        if (we) {
          uint32_t nv = (uint32_t)(mtime >> sh);
          for (int b = 0; b < 4; b++)
            if (sel & (1u << b)) nv = (nv & ~(0xFFu << (8 * b))) | (wdata & (0xFFu << (8 * b)));
          mtime = (mtime & ~(0xFFFFFFFFull << sh)) | ((uint64_t)nv << sh);
        }
        rdata = (uint32_t)(mtime >> sh);
      } else {
        err = true;
      }
      top->dBusWishbone_DAT_MISO = rdata;
      top->dBusWishbone_ACK = 1;
      top->dBusWishbone_ERR = err;
      dack = true;
    }
    top->timerInterrupt = mtime >= mtimecmp;
    top->softwareInterrupt = msip;
    top->externalInterruptArray = ext_irq;

    top->clk = 0;
    top->eval();
    top->clk = 1;
    top->eval();
    if (!top->reset && (cycle % MTIME_DIV) == 0) mtime++;
  }
}
